// DevSynt Candidate Data Normalization Code Node
// Normalizes payload structure from both Email and Form sources into a uniform schema

const item = $input.item.json;
let name = '';
let email = '';
let phone = '';
let source = '';
let role_applied = '';
let resume_text = '';

if (item.from && item.from.value) {
  // Email Intake Source
  source = 'email';
  name = item.from.value[0]?.name || item.from.value[0]?.address.split('@')[0] || 'Candidate';
  email = (item.from.value[0]?.address || '').toLowerCase().trim();

  // Extract role from Email Subject (e.g. "Application for Full Stack Engineer")
  const subject = item.subject || '';
  const roleMatch = subject.match(/for\s+([A-Za-z0-9\s\-\+]+)/i);
  role_applied = roleMatch ? roleMatch[1].trim() : 'Software Engineer';

  phone = item.phone || 'N/A';
  resume_text = item.text || item.html || 'Resume text content embedded in email body.';
} else {
  // Form / Webhook Source
  source = 'form';
  name = item.name || item.fullName || 'Candidate';
  email = (item.email || '').toLowerCase().trim();
  phone = item.phone || 'N/A';
  role_applied = item.role_applied || item.role || item.position || 'Software Engineer';
  resume_text = item.resume_text || item.resumeText || item.cover_letter || 'Resume text submitted via Google Form.';
}

return {
  json: {
    name,
    email,
    phone,
    source,
    role_applied,
    resume_text,
    applied_at: new Date().toISOString(),
    status: 'pending_review'
  }
};

