// Parse AI response and validate classification thresholds
const rawContent = $input.item.json.message?.content || $input.item.json.text || '{}';
let parsed = {};
try {
  parsed = JSON.parse(rawContent.replace(/```json|```/g, '').trim());
} catch (e) {
  parsed = {
    ats_score: 60,
    classification: 'Average',
    manager_notes: 'Failed to parse AI output automatically. Defaulted for manual review.'
  };
}

// Enforce strict scoring thresholds
let score = Number(parsed.ats_score) || 50;
score = Math.max(0, Math.min(100, score));

let classification = 'Average';
if (score >= 75) {
  classification = 'Strong';
} else if (score >= 50) {
  classification = 'Average';
} else {
  classification = 'Weak';
}

return {
  json: {
    candidate_id: $node["4. Store Candidate in Supabase"].json.id,
    name: $node["4. Store Candidate in Supabase"].json.name,
    email: $node["4. Store Candidate in Supabase"].json.email,
    role_applied: $node["4. Store Candidate in Supabase"].json.role_applied,
    ats_score: score,
    classification: classification,
    manager_notes: parsed.manager_notes || `ATS Score: ${score}/100 - ${classification}`,
    status: 'pending_review'
  }
};
